DO $role$
DECLARE
    existing record;
BEGIN
    SELECT oid, rolsuper, rolbypassrls, rolcanlogin, rolcreaterole, rolcreatedb, rolreplication
      INTO existing FROM pg_catalog.pg_roles WHERE rolname = 'mission_control_checkpointer';
    IF FOUND THEN
        IF existing.rolsuper OR existing.rolbypassrls OR existing.rolcanlogin
           OR existing.rolcreaterole OR existing.rolcreatedb OR existing.rolreplication THEN
            RAISE EXCEPTION 'existing role mission_control_checkpointer is not a restricted NOLOGIN role';
        END IF;
        IF EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member = existing.oid) THEN
            RAISE EXCEPTION 'existing role mission_control_checkpointer holds role memberships';
        END IF;
    ELSE
        CREATE ROLE mission_control_checkpointer NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE
            NOINHERIT NOREPLICATION;
    END IF;
END
$role$;
CREATE SCHEMA mission_control_runtime;
REVOKE ALL ON SCHEMA mission_control_runtime FROM PUBLIC;
REVOKE ALL ON SCHEMA mission_control_runtime FROM mission_control_checkpointer;
GRANT USAGE ON SCHEMA mission_control_runtime TO mission_control_checkpointer;

CREATE TABLE IF NOT EXISTS checkpoint_migrations (
    v INTEGER PRIMARY KEY
);

CREATE TABLE IF NOT EXISTS store_migrations (
    v INTEGER PRIMARY KEY
)

-- Add indexes for efficient TTL sweeping
CREATE INDEX IF NOT EXISTS idx_store_expires_at ON store (expires_at)
WHERE expires_at IS NOT NULL;

REVOKE ALL ON ALL TABLES IN SCHEMA mission_control_runtime FROM PUBLIC;
DO $grants$
DECLARE
    item record;
BEGIN
    FOR item IN
        SELECT DISTINCT n.nspname, c.relname, r.rolname
          FROM pg_catalog.pg_class c
          JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) acl
          JOIN pg_catalog.pg_roles r ON r.oid = acl.grantee
         WHERE n.nspname = 'mission_control_runtime' AND acl.grantee <> c.relowner
    LOOP
        EXECUTE pg_catalog.format(
            'REVOKE ALL ON %I.%I FROM %I', item.nspname, item.relname, item.rolname
        );
    END LOOP;
END
$grants$;
GRANT SELECT, INSERT, UPDATE, DELETE ON mission_control_runtime.checkpoints, mission_control_runtime.checkpoint_blobs, mission_control_runtime.checkpoint_writes, mission_control_runtime.store TO mission_control_checkpointer;
GRANT SELECT ON mission_control_runtime.checkpoint_migrations, mission_control_runtime.store_migrations TO mission_control_checkpointer;
